export function getQuinhaoMap(config = {}) {
  const id = typeof config === "string" ? config : config.mapId ?? "classic";
  const map = QUINHAO_MAPS.find((entry) => entry.id === id);
  if (!map || (typeof config === "object" && config.mapVersion !== undefined && config.mapVersion !== map.version)) {
    throw new Error("Mapa de QUINHÃO desconhecido ou incompatível.");
  }
  return map;
}
